/// <reference path="./sigApi.ApiBase.d.ts" />
/// <reference path="./sigApi.Unit.d.ts" />

declare namespace SigApi {
    interface ApiUnitManager extends ApiBase {
        /**
         * Finds a Unit
         * 
         * @param {string|number} id The id or the name of the unit
         * 
         * @returns {Unit|null} The Unit
         */
        getUnit(id: number | string): Unit | null
        /**
         * Gets the UnitList
         * 
         * @returns {Unit[]} The Unitlist
         */
        getUnitList(): Unit[]
        /**
         * Function to check if parameter object is a instanceof Unit.
         * This function can be used without importing the type Unit to be used with the instanceof operator.
         * @param {*} object Any object to type check
         * @returns {boolean} Returns true if parameter object is instanceof Unit, else false
         */
        instanceofUnit(object: any): boolean
        /**
         * Function to check if parameter object is a instanceof Formula.
         * This function can be used without importing the type Formula to be used with the instanceof operator.
         * @param {*} object Any object to type check
         * @returns {boolean} Returns true if parameter object is instanceof Formula, else false
         */
        instanceofFormula(object: any): boolean
    }
}
